function sortStatusText(header, direction) {
  if (direction === "none" || !header) return "Not sorted";
  return `Sorted by ${header.value ?? header.key}, ${direction}`;
}

function thresholdsText(
  { warning, error },
  locale,
) {
  const format = getNumberFormatter(locale);
  if (warning !== undefined && error !== undefined) {
    return `Warning at ${format.format(warning)}, error at ${format.format(error)}`;
  }
  if (warning !== undefined) return `Warning at ${format.format(warning)}`;
  if (error !== undefined) return `Error at ${format.format(error)}`;
  return "";
}

function valueRangeText(value, max, locale) {
  const format = getNumberFormatter(locale);
  return `${format.format(value)} of ${format.format(max)}`;
}

function itemRangeText(min, max, total) {
  if (total <= 0) return "0 items";
  return `${min.toLocaleString()}–${max.toLocaleString()} of ${total.toLocaleString()} item${max === 1 ? "" : "s"}`;
}
